fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

fn founder(years: i64, sex: Sex, maternal: u8, paternal: u8) -> Founder {
    Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles: common::dummy(maternal, paternal),
    }
}

/// Test data with these causes of death and the fertility of the old model at `rate`
/// (ADR-0017 section 5).
fn windowed(accident: f64, second: Option<f64>, rate: f64) -> Data {
    windowed_with(accident, second, rate, |_| {})
}

/// `windowed` with a change to its life course data.
fn windowed_with(
    accident: f64,
    second: Option<f64>,
    rate: f64,
    change: impl FnOnce(&mut serde_json::Value),
) -> Data {
    let (mut calibration, genome_map) =
        common::death_files(accident, second, common::repository_diseases());
    let mut demography = common::demography();
    common::window_fertility(&mut calibration, &mut demography, rate);
    change(&mut demography);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

/// The test data of "clan": accident 0.02 per year, senescence off, or, for "fever",
/// senescence with `a` = `second` per year; the repository's diseases; 0.25 per attempt.
fn clan_data(second: Option<f64>) -> Data {
    windowed(0.02, second, 0.25)
}

/// The test data of "blight": accident 0.1 and senescence `a` 0.02 per year, so that the
/// first woman dies while pregnant (`tools/state_reference.py`).
fn blight_data() -> Data {
    windowed(0.1, Some(0.02), 0.25)
}

/// The test data of "twins": "clan" with twins at every conception, identical 0.3 and
/// fraternal 0.7.
fn twins_data() -> Data {
    windowed_with(0.02, None, 0.25, |demography| {
        let values = &mut demography["values"];
        values["core:twins_identical"]["value"] = serde_json::json!(0.3);
        values["core:twins_fraternal"]["value"] = serde_json::json!(0.7);
    })
}

fn clan_start() -> Input {
    const DUMMY: u8 = 1;
    const WILD: u8 = 0;
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: DataId::new("test:clan").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(20, Sex::Female, WILD, DUMMY),
            founder(22, Sex::Male, DUMMY, WILD),
            founder(12, Sex::Female, DUMMY, DUMMY),
            founder(30, Sex::Male, WILD, WILD),
            founder(46, Sex::Female, WILD, WILD),
            founder(46, Sex::Male, WILD, WILD),
        ],
        couples: vec![
            Couple { woman: 0, man: 1 },
            Couple { woman: 2, man: 3 },
            Couple { woman: 4, man: 5 },
        ],
    })
}

fn clan() -> World {
    let mut world = World::new(clan_data(None));
    world.submit(clan_start()).expect("accepted");
    world
}

fn twins() -> World {
    let mut world = World::new(twins_data());
    world.submit(clan_start()).expect("accepted");
    world
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn new(mut world: World) -> Run {
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn advance(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }
}

/// Each couple whose woman's fertility has not ended gets a monthly series of attempts
/// from month 1: the first couple and the girl's; the couple of 46 none.
#[test]
fn couples_try_once_a_month_while_she_can_conceive() {
    let run = Run::new(clan());
    assert_eq!(run.save(), hex(CLAN_SAVE_AFTER_START));
}

/// The attempt in month 5 succeeds: `core:conception` with the plan of the series, the
/// draw of the attempt and the draw of the multiple birth (one child here) as causes, then
/// the meiosis of the mother and of the father, each caused by the conception and the
/// rule, with its own draw (the father's also with the draw of the sex chromosome). Her
/// attempts end; the pregnancy is in the state.
#[test]
fn a_conception_fixes_the_child() {
    let mut run = Run::new(clan());
    run.advance(5 * MONTH - 1);
    let before = run.log.len();
    run.advance(5 * MONTH);
    let entries: Vec<Vec<u8>> = run.log[before..]
        .iter()
        .map(|entry| postcard::to_allocvec(entry).expect("encodes"))
        .collect();
    assert_eq!(entries, CLAN_CONCEPTION_ENTRIES.map(hex));
    let json: Vec<String> = run.log[before..]
        .iter()
        .map(|entry| serde_json::to_string(entry).expect("json"))
        .collect();
    assert_eq!(
        json[0],
        r#"{"id":17,"t":12096000,"subjects":[{"sim":1},{"sim":2}],"causes":[{"plan":{"by":8,"planned_at":0}},{"random":{"tag":"0000000000000003","subject":"d0a158c16220f6dd","occasion":"0000000000000005","detail":"3e8b5cdead66f5f6"}},{"random":{"tag":"0000000000000011","subject":"cd0785dcdac6a473","occasion":"0000000000000000","detail":"0000000000000000"}}],"payload":{"core:conception":{"lineage_key":"cd0785dcdac6a473"}}}"#
    );
    // The two meioses (ADR-0004 section 7): causes the conception and the rule only; the
    // payloads are pinned as bytes above (tools/state_reference.py with the meiosis of
    // tools/meiosis_reference.py).
    for meiosis in &json[1..] {
        assert!(meiosis.contains(r#""causes":[{"event":17},{"rule":"core:meiosis"}]"#));
    }
    assert_eq!(run.save(), hex(CLAN_SAVE_AFTER_CONCEPTION));
}

/// The first woman has a child in month 15 and conceives again and again: eight times by
/// the end of year 7 (months 5, 17, 28, 42, 59, 74, 90, 101); at the end of year 7 she is
/// pregnant again. The girl's attempts have chance 0 until her 18th birthday; she dies in
/// month 83.9 without a child.
#[test]
fn the_first_woman_conceives_again_and_again() {
    let mut run = Run::new(clan());
    run.advance(8 * Y - 1);
    assert_eq!(run.save(), hex(CLAN_SAVE_AFTER_YEAR_7));
}

/// With "fever" (senescence `a` 0.5) the father (sim 2) dies of senescence in month 20.8,
/// while she is pregnant since month 17: the pregnancy goes on, his child (sim 8) is born in
/// month 27. Her first child (sim 7) was born in month 15.
#[test]
fn a_child_is_born_after_the_death_of_its_father() {
    let mut world = World::new(clan_data(Some(0.5)));
    world.submit(clan_start()).expect("accepted");
    let mut run = Run::new(world);
    let child = sim_core::ids::SimId::try_from(8).expect("valid");
    run.advance(27 * MONTH);
    assert_eq!(
        run.world.state().born(child),
        Some(SimTime::from_secs(27 * MONTH))
    );
    // A save with the father in the archive and his child born after his death loads.
    World::load(&run.save(), clan_data(Some(0.5))).expect("loads");
    run.advance(4 * Y - 1);
    assert_eq!(run.save(), hex(CLAN_FEVER_SAVE_AFTER_YEAR_3));
}

/// With "blight" (accident 0.1, senescence `a` 0.02) the first woman dies of accident in
/// month 22.2, pregnant with her second child since month 17: the pregnancy ends with her,
/// her conception stays counted, and the child's key is no longer known, also not to a
/// loaded world.
#[test]
fn her_death_ends_the_pregnancy() {
    let mut world = World::new(blight_data());
    world.submit(clan_start()).expect("accepted");
    let tag = DataId::new("test:clan").expect("valid");
    let child = LineageKey::child(
        LineageKey::founder(&tag, 0),
        LineageKey::founder(&tag, 1),
        1,
        0,
    );
    let mut run = Run::new(world);
    run.advance(HER_BLIGHT - 1);
    assert!(run.world.state().knows_lineage_key(child));
    run.advance(HER_BLIGHT);
    assert!(!run.world.state().knows_lineage_key(child));
    let (loaded, _) = World::load(&run.save(), blight_data()).expect("loads");
    assert!(!loaded.state().knows_lineage_key(child));
    run.advance(2 * Y - 1);
    assert_eq!(run.save(), hex(CLAN_BLIGHT_SAVE_AFTER_YEAR_1));
}

/// With the switch of the hereditary diseases on, a child with the dummy allele twice is
/// exposed from its birth on (the girl from the start); the save loads and goes on as
/// the uninterrupted run.
#[test]
fn a_child_is_exposed_from_its_birth() {
    let on = || {
        let Input::Start(mut start) = clan_start() else {
            unreachable!("a start")
        };
        start.world_params.hereditary_diseases = true;
        let mut world = World::new(clan_data(None));
        world.submit(Input::Start(start)).expect("accepted");
        Run::new(world)
    };
    let mut run = on();
    run.advance(15 * MONTH);
    assert_eq!(run.save(), hex(CLAN_ON_SAVE_AFTER_BIRTH));
    let (loaded, years) = World::load(&run.save(), clan_data(None)).expect("loads");
    let mut rest = Run {
        world: loaded,
        out: YearOut {
            census: run.out.census.clone(),
            year_hashes: years,
        },
        log: run.log,
    };
    rest.advance(3 * Y - 1);
    let mut whole = on();
    whole.advance(3 * Y - 1);
    assert_eq!(rest.world.state_hash(), whole.world.state_hash());
    assert_eq!(log_hash(&rest.log), log_hash(&whole.log));
}

/// Ten months after the conception she gives birth: a new sim with the next ID, born in
/// that second, with its parents; the creation entry `core:birth` names child, mother
/// and father and has the plan of the conception and the rule `core:gestation` as
/// causes. Her attempts begin again in the next month.
#[test]
fn a_birth_brings_the_child_into_the_world() {
    let mut run = Run::new(clan());
    run.advance(15 * MONTH - 1);
    let before = run.log.len();
    run.advance(15 * MONTH);
    assert_eq!(run.log.len(), before + 1);
    let entry = &run.log[before];
    assert_eq!(
        postcard::to_allocvec(entry).expect("encodes"),
        hex(CLAN_BIRTH_ENTRY)
    );
    assert_eq!(
        serde_json::to_string(entry).expect("json"),
        r#"{"id":26,"t":36288000,"subjects":[{"sim":7},{"sim":1},{"sim":2}],"causes":[{"plan":{"by":17,"planned_at":12096000}},{"rule":"core:gestation"}],"payload":{"core:birth":{"lineage_key":"cd0785dcdac6a473"}}}"#
    );
    assert_eq!(run.save(), hex(CLAN_SAVE_AFTER_BIRTH));
    assert_eq!(run.world.state().living(), 7);
}

/// A couple of `Start` names founders of the list.
#[test]
fn a_couple_of_unknown_founders_is_rejected() {
    let mut world = World::new(clan_data(None));
    let Input::Start(mut start) = clan_start() else {
        unreachable!("a start")
    };
    start.couples.push(Couple { woman: 0, man: 9 });
    assert_eq!(
        world.submit(Input::Start(start)).err(),
        Some(InputRejected {
            code: RejectCode::UnknownFounder
        })
    );
    assert!(world.input_log().is_empty());
}

/// Her last attempt is the one before the end of her fertility (ADR-0017 section 4): after
/// it her series ends, so that a pending attempt always lies before that age. Under the
/// window she turns 45 at the start of month 3: she tries in months 1 and 2 (at a chance of
/// 1e-9, never with success here).
#[test]
fn the_last_attempt_before_the_end_of_fertility_ends_the_series() {
    let Input::Start(mut start) = clan_start() else {
        unreachable!("a start")
    };
    start.founders.truncate(2);
    start.founders[0].born = SimTime::from_secs(3 * MONTH - 45 * Y);
    start.couples.truncate(1);
    let data = || windowed(0.02, None, 1e-9);
    let mut world = World::new(data());
    world.submit(Input::Start(start)).expect("accepted");
    let mut run = Run::new(world);
    let loads = |run: &Run| {
        let bytes = run.save();
        let (loaded, years) = World::load(&bytes, data()).expect("loads");
        assert_eq!(loaded.save(&years).expect("saves"), bytes);
    };
    run.advance(MONTH);
    let with_attempts = run.world.pending_events();
    loads(&run);
    run.advance(2 * MONTH);
    assert_eq!(run.world.pending_events(), with_attempts - 1);
    loads(&run);
    run.advance(Y);
    assert_eq!(run.world.pending_events(), with_attempts - 1);
}

/// Loading and going on gives the uninterrupted run, before, at and after the first
/// conception and birth, across the girl's 18th birthday and her death.
#[test]
fn save_load_continue_across_conceptions() {
    let end = 8 * Y - 1;
    let mut whole = Run::new(clan());
    whole.advance(end);
    for stop in [
        0,
        5 * MONTH - 1,
        5 * MONTH,
        Y,
        15 * MONTH - 1,
        15 * MONTH,
        78 * MONTH,
        84 * MONTH,
        95 * MONTH,
        7 * Y,
    ] {
        let mut part = Run::new(clan());
        part.advance(stop);
        let bytes = part.save();
        let (loaded, years) = World::load(&bytes, clan_data(None)).expect("loads");
        assert_eq!(loaded.save(&years).expect("saves"), bytes, "stop {stop}");
        let mut rest = Run {
            world: loaded,
            out: YearOut {
                census: part.out.census.clone(),
                year_hashes: years,
            },
            log: part.log,
        };
        rest.advance(end);
        assert_eq!(rest.out.year_hashes, whole.out.year_hashes, "stop {stop}");
        assert_eq!(log_hash(&rest.log), log_hash(&whole.log), "stop {stop}");
        assert_eq!(
            rest.world.state_hash(),
            whole.world.state_hash(),
            "stop {stop}"
        );
    }
}

/// On the repository's data (the curves of 5.6, the rate 0.20, a pause of 12 months, the
/// wish of 11.3) the golden scenario `tests/scenarios/dummy.json` (`tools/golden_reference.py`):
/// sim 1, 30 at the start, and sim 5, 25, each wish three children. Sim 1 conceives in
/// months 7, 32 and 74 and bears sims 8, 10 and 12 in months 17, 42 and 84; sim 5
/// conceives in months 2, 31 and 63 and bears sims 7, 9 and 11 in months 12, 41 and 73.
/// After each birth the series waits for the pause; once the wish is reached no series,
/// no further conception in the thirty years.
#[test]
fn the_wish_and_the_pause_on_the_repository_data() {
    let text = include_str!("../../../tests/scenarios/dummy.json");
    let value: serde_json::Value = serde_json::from_str(text).expect("json");
    let start: Input =
        serde_json::from_value(serde_json::json!({ "start": value["start"] })).expect("a start");
    let mut world = World::new(common::data());
    world.submit(start).expect("accepted");
    let mut run = Run::new(world);
    run.advance(30 * Y - 1);
    let conceived = |woman: u64| -> Vec<i64> {
        run.log
            .iter()
            .filter(|entry| {
                matches!(entry.payload, sim_core::log::LogPayload::Conception { .. })
                    && entry.subjects.first()
                        == Some(&sim_core::log::Subject::Sim(
                            sim_core::ids::SimId::try_from(woman).expect("valid"),
                        ))
            })
            .map(|entry| entry.t.as_secs() / MONTH)
            .collect()
    };
    assert_eq!(conceived(1), [7, 32, 74]);
    assert_eq!(conceived(5), [2, 31, 63]);
    let born = |mother: u64| -> Vec<(u64, i64)> {
        run.world
            .state()
            .pedigree()
            .persons
            .iter()
            .filter(|person| person.mother.map(|id| id.get()) == Some(mother))
            .map(|person| (person.sim.get(), person.born.as_secs() / MONTH))
            .collect()
    };
    assert_eq!(born(1), [(8, 17), (10, 42), (12, 84)]);
    assert_eq!(born(5), [(7, 12), (9, 41), (11, 73)]);
}

/// The entries of the log from `from` on, as bytes and as JSON.
fn entries(run: &Run, from: usize) -> (Vec<Vec<u8>>, Vec<String>) {
    let entries = &run.log[from..];
    let bytes = entries
        .iter()
        .map(|entry| postcard::to_allocvec(entry).expect("encodes"))
        .collect();
    let json = entries
        .iter()
        .map(|entry| serde_json::to_string(entry).expect("json"))
        .collect();
    (bytes, json)
}

/// Fraternal twins (design note of the twins, sections 1 to 3): the draw of the multiple
/// birth at the key of the first child gives two children of one conception number, each
/// with its own key and its own zygote. Per child its `core:conception` entry with the
/// plan, the attempt draw and the multiple draw as causes, followed by the two meioses of
/// its zygote; the pregnancy holds both.
#[test]
fn fraternal_twins_are_conceived_together() {
    let mut run = Run::new(twins());
    run.advance(5 * MONTH - 1);
    let before = run.log.len();
    run.advance(5 * MONTH);
    let (bytes, json) = entries(&run, before);
    assert_eq!(bytes, TWINS_CONCEPTION_ENTRIES.map(hex));
    let causes = r#""causes":[{"plan":{"by":8,"planned_at":0}},{"random":{"tag":"0000000000000003","subject":"d0a158c16220f6dd","occasion":"0000000000000005","detail":"3e8b5cdead66f5f6"}},{"random":{"tag":"0000000000000011","subject":"cd0785dcdac6a473","occasion":"0000000000000000","detail":"0000000000000000"}}]"#;
    for (at, id, key) in [(0, 17, "cd0785dcdac6a473"), (3, 20, "c6f053deea8481ab")] {
        assert!(
            json[at].starts_with(&format!(r#"{{"id":{id},"#)),
            "{}",
            json[at]
        );
        assert!(json[at].contains(causes), "{}", json[at]);
        let payload = format!(r#""payload":{{"core:conception":{{"lineage_key":"{key}"}}}}"#);
        assert!(json[at].contains(&payload), "{}", json[at]);
        for meiosis in &json[at + 1..at + 3] {
            let caused = format!(r#""causes":[{{"event":{id}}},{{"rule":"core:meiosis"}}]"#);
            assert!(meiosis.contains(&caused), "{meiosis}");
        }
    }
    assert_eq!(run.save(), hex(TWINS_SAVE_AFTER_CONCEPTION));
}

/// The twins are born in one second, in the order of their index, with consecutive SimIds
/// (7 and 8), each with its creation entry planned by its own conception entry; the mother
/// has two live births.
#[test]
fn twins_are_born_in_one_second() {
    let mut run = Run::new(twins());
    run.advance(15 * MONTH - 1);
    let before = run.log.len();
    run.advance(15 * MONTH);
    let (bytes, json) = entries(&run, before);
    assert_eq!(bytes, TWINS_BIRTH_ENTRIES.map(hex));
    assert_eq!(
        json,
        [
            r#"{"id":29,"t":36288000,"subjects":[{"sim":7},{"sim":1},{"sim":2}],"causes":[{"plan":{"by":17,"planned_at":12096000}},{"rule":"core:gestation"}],"payload":{"core:birth":{"lineage_key":"cd0785dcdac6a473"}}}"#,
            r#"{"id":30,"t":36288000,"subjects":[{"sim":8},{"sim":1},{"sim":2}],"causes":[{"plan":{"by":17,"planned_at":12096000}},{"rule":"core:gestation"}],"payload":{"core:birth":{"lineage_key":"c6f053deea8481ab"}}}"#,
        ]
    );
    assert_eq!(run.save(), hex(TWINS_SAVE_AFTER_BIRTH));
    assert_eq!(run.world.state().living(), 8);
}

/// Identical twins share their two meioses (ADR-0004 section 7): the entry of the first
/// child, its two meioses, the entry of the second; born in month 27 with one genome and
/// one sex, each with its own key.
#[test]
fn identical_twins_share_their_genome() {
    let mut run = Run::new(twins());
    run.advance(17 * MONTH - 1);
    let before = run.log.len();
    run.advance(17 * MONTH);
    let (bytes, json) = entries(&run, before);
    assert_eq!(bytes, TWINS_IDENTICAL_ENTRIES.map(hex));
    for (at, key) in [(0, "e6f81c92e2979324"), (3, "978df792f8def813")] {
        let payload = format!(r#""payload":{{"core:conception":{{"lineage_key":"{key}"}}}}"#);
        assert!(json[at].contains(&payload), "{}", json[at]);
    }
    run.advance(27 * MONTH);
    let pedigree = run.world.state().pedigree();
    let twin = |sim: u64| {
        let person = pedigree
            .persons
            .iter()
            .find(|person| person.sim.get() == sim)
            .expect("born");
        (
            person.lineage_key.get(),
            person.sex,
            person.alleles.clone(),
            person.born,
        )
    };
    let (first, second) = (twin(9), twin(10));
    assert_eq!(
        (first.0, second.0),
        (0xe6f8_1c92_e297_9324, 0x978d_f792_f8de_f813)
    );
    assert_eq!(
        (first.1, first.3),
        (Sex::Female, SimTime::from_secs(27 * MONTH))
    );
    assert_eq!(
        (&first.1, &first.2, first.3),
        (&second.1, &second.2, second.3)
    );
}

/// Three years of "twins": the first woman conceives in the months of "clan" (5, 17, 28,
/// 42) and every conception gives twins: fraternal, identical, fraternal, fraternal. Six
/// children are born (sims 7 to 12); at the end of year 3 she is pregnant with the fourth
/// pair and has six live births.
#[test]
fn every_conception_gives_twins() {
    let mut run = Run::new(twins());
    run.advance(4 * Y - 1);
    let children: Vec<(u64, u64, Sex, i64)> = run
        .world
        .state()
        .pedigree()
        .persons
        .iter()
        .filter(|person| person.mother.is_some())
        .map(|person| {
            let born = person.born.as_secs() / MONTH;
            (person.sim.get(), person.lineage_key.get(), person.sex, born)
        })
        .collect();
    assert_eq!(
        children,
        [
            (7, 0xcd07_85dc_dac6_a473, Sex::Male, 15),
            (8, 0xc6f0_53de_ea84_81ab, Sex::Male, 15),
            (9, 0xe6f8_1c92_e297_9324, Sex::Female, 27),
            (10, 0x978d_f792_f8de_f813, Sex::Female, 27),
            (11, 0x9d34_2df7_0eec_fc33, Sex::Female, 38),
            (12, 0x6861_b08e_1003_913d, Sex::Male, 38),
        ]
    );
    assert_eq!(run.save(), hex(TWINS_SAVE_AFTER_YEAR_3));
    let hashes: Vec<u64> = run.out.year_hashes.iter().map(|year| year.hash).collect();
    assert_eq!(hashes, TWINS_YEAR_HASHES);
    assert_eq!(log_hash(&run.log), TWINS_LOG_HASH);
}

/// Saving and loading between the conception and the birth of twins changes nothing.
#[test]
fn save_load_continue_across_twins() {
    let end = 4 * Y - 1;
    let mut whole = Run::new(twins());
    whole.advance(end);
    for stop in [
        5 * MONTH - 1,
        5 * MONTH,
        15 * MONTH - 1,
        15 * MONTH,
        17 * MONTH,
        27 * MONTH,
        3 * Y,
    ] {
        let mut part = Run::new(twins());
        part.advance(stop);
        let bytes = part.save();
        let (loaded, years) = World::load(&bytes, twins_data()).expect("loads");
        assert_eq!(loaded.save(&years).expect("saves"), bytes, "stop {stop}");
        let mut rest = Run {
            world: loaded,
            out: YearOut {
                census: part.out.census.clone(),
                year_hashes: years,
            },
            log: part.log,
        };
        rest.advance(end);
        assert_eq!(rest.out.year_hashes, whole.out.year_hashes, "stop {stop}");
        assert_eq!(log_hash(&rest.log), log_hash(&whole.log), "stop {stop}");
        assert_eq!(
            rest.world.state_hash(),
            whole.world.state_hash(),
            "stop {stop}"
        );
    }
}

/// The thresholds of the multiple birth are strict (11.3: identical if `u < p_id`,
/// fraternal if `u < p_id + p_fr`). The draw of the first conception of "clan" is `u` =
/// 0.9059764199227032 (`tools/state_reference.py`, `twins_by_hand`): a rate equal to it
/// gives one child (a conception entry and its two meioses), one ulp above it twins
/// (identical: the second entry without meioses; fraternal: with its own two).
#[test]
fn a_draw_on_the_threshold_gives_one_child() {
    const U: f64 = 0.905_976_419_922_703_2;
    let above = f64::from_bits(U.to_bits() + 1);
    let cases = [
        ((U, 0.0), 3),
        ((0.0, U), 3),
        ((above, 0.0), 4),
        ((0.0, above), 6),
    ];
    for ((identical, fraternal), entries) in cases {
        let data = windowed_with(0.02, None, 0.25, |demography| {
            let values = &mut demography["values"];
            values["core:twins_identical"]["value"] = serde_json::json!(identical);
            values["core:twins_fraternal"]["value"] = serde_json::json!(fraternal);
        });
        let mut world = World::new(data);
        world.submit(clan_start()).expect("accepted");
        let mut run = Run::new(world);
        run.advance(5 * MONTH - 1);
        let before = run.log.len();
        run.advance(5 * MONTH);
        assert_eq!(
            run.log.len() - before,
            entries,
            "identical {identical}, fraternal {fraternal}"
        );
    }
}
